PostToolUse.command:
node -e "
const fs = require('fs');
const input = JSON.parse(fs.readFileSync('/dev/stdin', 'utf8'));
const tool = input.toolName || '';
const isFileWrite = ['create_file', 'replace_string_in_file', 'multi_replace_string_in_file', 'edit_notebook_file'].includes(tool);
if (isFileWrite) {
  const msg = '\n[code-quality-check] 刚写入了代码，请检查：\n1. 是否是补丁式代码（函数末尾追加 if、复制粘贴逻辑、flag 控制执行）？\n2. 函数是否超过 50 行，嵌套是否超过 3 层？\n3. Rust 代码是否使用了 unwrap()、不必要的 clone()？\n4. 是否有相似逻辑出现 3 次以上？\n5. 是否自己实现了有成熟库的功能？\n如有问题请指出并建议修改方向。无问题则跳过。';
  process.stdout.write(JSON.stringify({ systemMessage: msg }));
} else {
  process.stdout.write(JSON.stringify({ continue: true }));
}
"
